ans_97_str = """"""

ans_97 = int(ans_97_str.replace('\n', '').replace(' ', ''))

print(f"n = {n}")
print(f"n bits = {n.bit_length()}")
print(f"\nans_97 = {ans_97}")
print(f"ans_97 bits = {ans_97.bit_length()}")

# 验证
check = pow(ans_97, 2, n)
print(f"\nans_97² mod n = {check}")
print(f"ans_97² mod n == 97? {check == 97}")

if check != 97:
    print("\n[!] ans_97 验证失败，可能解析有问题")
    # 尝试修正
    # 计算 ans_97² - 97 应该是 n 的倍数
    diff = ans_97 * ans_97 - 97
    print(f"ans_97² - 97 = {diff}")
    print(f"gcd(ans_97² - 97, n) = {gcd(diff, n)}")

# 方法: 多项式 GCD
# 设 P(x) = x² + 3x + 3 (p 的多项式)
# Q(x) = x² + 5x + 7 (q 的多项式)
# 
# 我们知道 P(pp) = p | n, Q(pp) = q | n
#
